/**
 * Red-Black Tree implementation with insert, delete, search, and in-order iterator.
 */
class RedBlackTree {
  constructor() {
    this.root = null;
    this.NIL = new Node(null, null, null, null, false); // black sentinel
    this.NIL.left = this.NIL;
    this.NIL.right = this.NIL;
  }

  class Node {
    constructor(key, left, right, parent, isRed) {
      this.key = key;
      this.left = left;
      this.right = right;
      this.parent = parent;
      this.isRed = isRed;
    }
  }

  // Helper: rotate left at x
  rotateLeft(x) {
    const y = x.right;
    x.right = y.left;
    if (y.left !== this.NIL) y.left.parent = x;
    y.parent = x.parent;
    if (x.parent === this.NIL) {
      this.root = y;
    } else if (x === x.parent.left) {
      x.parent.left = y;
    } else {
      x.parent.right = y;
    }
    y.left = x;
    x.parent = y;
  }

  // Helper: rotate right at x
  rotateRight(x) {
    const y = x.left;
    x.left = y.right;
    if (y.right !== this.NIL) y.right.parent = x;
    y.parent = x.parent;
    if (x.parent === this.NIL) {
      this.root = y;
    } else if (x === x.parent.right) {
      x.parent.right = y;
    } else {
      x.parent.left = y;
    }
    y.right = x;
    x.parent = y;
  }

  // Fix red-black properties after insertion
  insertFixup(x) {
    while (x.parent.isRed) {
      if (x.parent === x.parent.parent.left) {
        const uncle = x.parent.parent.right;
        if (uncle.isRed) {
          x.parent.isRed = false;
          uncle.isRed = false;
          x.parent.parent.isRed = true;
          x = x.parent.parent;
        } else {
          if (x === x.parent.right) {
            x = x.parent;
            this.rotateLeft(x);
          }
          x.parent.isRed = false;
          x.parent.parent.isRed = true;
          this.rotateRight(x.parent.parent);
        }
      } else {
        const uncle = x.parent.parent.left;
        if (uncle.isRed) {
          x.parent.isRed = false;
          uncle.isRed = false;
          x.parent.parent.isRed = true;
          x = x.parent.parent;
        } else {
          if (x === x.parent.left) {
            x = x.parent;
            this.rotateRight(x);
          }
          x.parent.isRed = false;
          x.parent.parent.isRed = true;
          this.rotateLeft(x.parent.parent);
        }
      }
